<script setup lang="ts">
import { ref,onMounted,onUnmounted,computed } from 'vue'
import { api,bytes,user } from '../api'
const recentRuns=ref<any[]>([]),recentAudit=ref<any[]>([])
const summary=ref<Record<string,number>>({})
const metric=ref<any>({}),history=ref<any[]>([]),host=ref<any>({}),alerts=ref<any[]>([]),error=ref(''),range=ref('1h'),last=ref('')
let timer:ReturnType<typeof setInterval>|undefined,loading=false
async function refresh(){if(loading)return;loading=true;try{const [m,h,a,o]=await Promise.all([api('metrics'),api('history?range='+range.value),api('alerts'),api('overview')]);summary.value=o;metric.value=m;history.value=h;alerts.value=a;last.value=m.lastSuccess?new Date(m.lastSuccess*1000).toLocaleTimeString():'尚无有效采样';error.value='';if(user.value?.role==='admin'){const [runs,audit]=await Promise.all([api('runs?limit=5'),api('audit?limit=5')]);recentRuns.value=runs;recentAudit.value=audit}}catch(e){error.value=String(e)}finally{loading=false}}
const points=computed(()=>history.value.map((m,i)=>`${i*800/Math.max(1,history.value.length-1)},${180-Math.min(100,m.cpu)*1.6}`).join(' '))
onMounted(async()=>{refresh();try{host.value=await api('host')}catch{}timer=setInterval(refresh,10000)})
onUnmounted(()=>clearInterval(timer))
</script>
<template><p v-if="error" class="error">{{error}}</p><div v-if="!metric.available" class="notice">监控数据不可用：{{metric.error||'等待首次采样'}}</div><div class="stat-grid"><section v-for="item in [{label:'CPU 使用率',value:metric.cpu,sub:host.cpus+' 核 · 单核配额'},{label:'内存使用率',value:metric.memory,sub:bytes(metric.memoryUsed||0)+' / '+bytes(metric.memoryTotal||0)},{label:'系统磁盘',value:metric.disk,sub:bytes(metric.diskUsed||0)+' / '+bytes(metric.diskTotal||0)},{label:'交换空间',value:metric.swap,sub:'系统 Swap 使用情况'}]" :key="item.label" class="card stat"><div class="stat-label">{{item.label}}<span class="stat-icon">◈</span></div><div class="stat-value">{{metric.available?(item.value||0).toFixed(1):'—'}}<small>%</small></div><div class="meter"><i :style="{width:(item.value||0)+'%'}"></i></div><p class="muted small">{{metric.available?item.sub:'数据不可用'}}</p></section></div><div class="stat-grid"><a v-for="item in [{key:'sites',label:'受管网站',route:'sites'},{key:'certificates',label:'证书临期',route:'certificates'},{key:'services',label:'异常服务（已监控）',route:'services'},{key:'alerts',label:'未恢复告警',route:'alerts'}]" :key="item.key" class="card section-head" :href="'#'+item.route"><span class="muted small">{{item.label}}</span><strong>{{summary[item.key]??'—'}}</strong></a></div><div class="dashboard-grid"><section class="card chart"><div class="section-head"><div><h2>资源趋势</h2><p class="muted small">CPU 使用率 · 每 10 秒采集</p></div><select v-model="range" @change="refresh"><option value="1h">最近 1 小时</option><option value="24h">最近 24 小时</option><option value="7d">最近 7 天</option><option value="30d">最近 30 天</option></select></div><svg viewBox="0 0 800 200" role="img" aria-label="CPU 使用率趋势"><defs><linearGradient id="fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#3978f6" stop-opacity=".17"/><stop offset="1" stop-color="#3978f6" stop-opacity="0"/></linearGradient></defs><path v-for="y in [20,60,100,140,180]" :key="y" :d="`M0 ${y} H800`" stroke="#edf0f5" stroke-dasharray="4 5"/><polygon v-if="history.length>1&&points" :points="'0,180 '+points+' 800,180'" fill="url(#fill)"/><polyline v-if="history.length>1" :points="points" fill="none" stroke="#3978f6" stroke-width="2.5"/></svg><div class="section-head small muted"><span>历史采样 · {{history.length}} 个数据点</span><span>最后更新 {{last}}</span></div></section><section class="card"><h2>服务器概览</h2><dl class="details"><dt>主机名</dt><dd>{{host.hostname||'—'}}</dd><dt>操作系统</dt><dd>{{host.os}} / {{host.architecture}}</dd><dt>内核</dt><dd>{{host.kernel||'—'}}</dd><dt>网络接收</dt><dd>{{metric.available?bytes(metric.rx||0)+'/s':'—'}}</dd><dt>网络发送</dt><dd>{{metric.available?bytes(metric.tx||0)+'/s':'—'}}</dd><dt>磁盘读取</dt><dd>{{metric.available?bytes(metric.diskRead||0)+'/s':'—'}}</dd><dt>磁盘写入</dt><dd>{{metric.available?bytes(metric.diskWrite||0)+'/s':'—'}}</dd><dt>系统负载</dt><dd>{{metric.load||'—'}}</dd></dl><div class="notice small">面板使用单进程采集，多个页面共享监控数据。</div></section></div><section class="card"><div class="section-head"><h2>最近告警</h2><a href="#alerts">查看全部 →</a></div><div v-if="!alerts.length" class="empty"><span class="healthy">✓</span><strong>暂无告警记录</strong><p class="muted">连续异常达到规则持续时间后会在这里显示</p></div><div v-for="a in alerts.slice(0,5)" :key="a.id" class="list-row"><span :class="['badge',a.active?'warning':'success']">{{a.active?'告警中':'已恢复'}}</span><span>{{a.message}}</span><time class="muted">{{new Date(a.updated*1000).toLocaleString()}}</time></div></section><div v-if="user?.role==='admin'" class="dashboard-grid"><section class="card"><div class="section-head"><h2>最近任务</h2><a href="#tasks">查看任务 →</a></div><div v-for="run in recentRuns" :key="run.id" class="list-row"><span class="badge">{{run.status}}</span><span>任务 #{{run.task_id}}</span><time class="muted">{{new Date(run.started*1000).toLocaleString()}}</time></div><p v-if="!recentRuns.length" class="empty">暂无执行记录</p></section><section class="card"><div class="section-head"><h2>最近操作</h2><a href="#security">操作审计 →</a></div><div v-for="entry in recentAudit" :key="entry.id" class="list-row"><span>{{entry.user}}</span><span class="muted">{{entry.action}}</span></div><p v-if="!recentAudit.length" class="empty">暂无操作记录</p></section></div></template>
